import 'dart:io';
import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as p;

import 'tables.dart';

// ─── Generated file (run: flutter pub run build_runner build) ─────────────────
// This part file will be generated by drift_dev.
part 'app_database.g.dart';

/// Central Drift database.
///
/// Usage:
///   final db = AppDatabase();
///   final settings = await db.getAllSettings();
///
/// All DAOs (Data Access Objects) are defined here as simple query methods
/// so each service can call them directly without coupling to Drift internals.
@DriftDatabase(tables: [
  SettingsTable,
  PricesTable,
  AssetsTable,
  PrintersTable,
  VouchersTable,
  SalesTable,
  SessionsTable,
  AdminAuthTable,
])
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(_openConnection());
  AppDatabase.forTesting(super.e);

  @override
  int get schemaVersion => 2;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        onCreate: (m) async {
          await m.createAll();
        },
        onUpgrade: (m, from, to) async {
          if (from < 2) {
            await m.createTable(salesTable);
            try {
              await customStatement(
                  "UPDATE vouchers_table SET status = 0 WHERE status = 'active';");
              await customStatement(
                  "UPDATE vouchers_table SET status = 1 WHERE status = 'used';");
              await customStatement(
                  "UPDATE vouchers_table SET status = 2 WHERE status = 'voided';");
              await customStatement('''
                INSERT OR IGNORE INTO sales_table (code, location_id, tier_char, serial, price_snapshot, status, expires_at, created_at, redeemed_at)
                SELECT code, location_id, tier_char, serial, price_snapshot, 1, expires_at, created_at, COALESCE(redeemed_at, created_at)
                FROM vouchers_table WHERE status = 1;
              ''');
            } catch (_) {}
          }
        },
      );

  // ─── Settings ───────────────────────────────────────────────────────────────

  Future<String?> getSetting(String key) async {
    final row = await (select(settingsTable)..where((t) => t.key.equals(key))).getSingleOrNull();
    return row?.value;
  }

  Future<void> setSetting(String key, String value) =>
      into(settingsTable).insertOnConflictUpdate(SettingsTableCompanion(
        key: Value(key),
        value: Value(value),
      ));

  Future<List<SettingEntry>> getAllSettings() => select(settingsTable).get();

  // ─── Prices ─────────────────────────────────────────────────────────────────

  Future<List<PriceEntry>> getAllPrices() => select(pricesTable).get();

  Future<void> setPrice(String tierChar, double price) =>
      into(pricesTable).insertOnConflictUpdate(PricesTableCompanion(
        tierChar: Value(tierChar),
        price: Value(price),
      ));

  // ─── Assets ─────────────────────────────────────────────────────────────────

  Future<List<AssetEntry>> getAssetsByType(String type) =>
      (select(assetsTable)..where((t) => t.type.equals(type))).get();

  Future<int> insertAsset(AssetsTableCompanion asset) =>
      into(assetsTable).insert(asset);

  Future<void> deleteAsset(int id) =>
      (delete(assetsTable)..where((t) => t.id.equals(id))).go();

  // ─── Printers ───────────────────────────────────────────────────────────────

  Future<List<PrinterEntry>> getAllPrinters() => select(printersTable).get();

  Future<void> upsertPrinter(PrintersTableCompanion printer) =>
      into(printersTable).insertOnConflictUpdate(printer);

  Future<void> deletePrinter(String id) =>
      (delete(printersTable)..where((t) => t.id.equals(id))).go();

  Future<void> setDefaultPrinter(String id) async {
    await (update(printersTable)).write(const PrintersTableCompanion(isDefault: Value(false)));
    await (update(printersTable)..where((t) => t.id.equals(id)))
        .write(const PrintersTableCompanion(isDefault: Value(true)));
  }

  // ─── Vouchers ───────────────────────────────────────────────────────────────

  Future<VoucherEntry?> getVoucher(String code) =>
      (select(vouchersTable)..where((t) => t.code.equals(code))).getSingleOrNull();

  Future<List<VoucherEntry>> getAllVouchers() => select(vouchersTable).get();

  Future<void> insertVoucher(VouchersTableCompanion v) =>
      into(vouchersTable).insert(v);

  Future<void> updateVoucherStatus(String code, int status, {DateTime? redeemedAt, String? voidReason}) =>
      (update(vouchersTable)..where((t) => t.code.equals(code))).write(VouchersTableCompanion(
        status: Value(status),
        redeemedAt: redeemedAt != null ? Value(redeemedAt) : const Value.absent(),
        voidReason: voidReason != null ? Value(voidReason) : const Value.absent(),
      ));

  // ─── Sales ──────────────────────────────────────────────────────────────────

  Future<List<SaleEntry>> getAllSales() => select(salesTable).get();

  Future<void> insertSale(SalesTableCompanion sale) =>
      into(salesTable).insertOnConflictUpdate(sale);

  // ─── Sessions ───────────────────────────────────────────────────────────────

  Future<List<SessionEntry>> getAllSessions() => select(sessionsTable).get();

  Future<void> insertSession(SessionsTableCompanion session) =>
      into(sessionsTable).insert(session);

  Future<void> updateSession(String sessionId, SessionsTableCompanion data) =>
      (update(sessionsTable)..where((t) => t.sessionId.equals(sessionId))).write(data);

  Future<List<SessionEntry>> getSessionsOlderThan(DateTime cutoff) =>
      (select(sessionsTable)..where((t) => t.createdAt.isSmallerThanValue(cutoff))).get();

  Future<void> deleteSession(String sessionId) =>
      (delete(sessionsTable)..where((t) => t.sessionId.equals(sessionId))).go();

  // ─── Admin Auth ─────────────────────────────────────────────────────────────

  Future<AdminAuthEntry?> getAdminAuth() =>
      (select(adminAuthTable)..limit(1)).getSingleOrNull();

  Future<void> upsertAdminAuth(String hash) async {
    final existing = await getAdminAuth();
    if (existing == null) {
      await into(adminAuthTable).insert(AdminAuthTableCompanion(
        passwordHash: Value(hash),
        updatedAt: Value(DateTime.now()),
      ));
    } else {
      await (update(adminAuthTable)..where((t) => t.id.equals(existing.id))).write(AdminAuthTableCompanion(
        passwordHash: Value(hash),
        updatedAt: Value(DateTime.now()),
      ));
    }
  }

  // ─── Cleanup ─────────────────────────────────────────────────────────────────

  /// Returns sessions created before [cutoff] — used by StorageService cleanup.
  Future<List<SessionEntry>> getExpiredSessions(DateTime cutoff) =>
      getSessionsOlderThan(cutoff);
}

// ─── DB connection factory ────────────────────────────────────────────────────

LazyDatabase _openConnection() {
  return LazyDatabase(() async {
    final dir = await getApplicationDocumentsDirectory();
    final file = File(p.join(dir.path, 'picnprint.db'));
    return NativeDatabase.createInBackground(file);
  });
}
